# -*- coding: utf-8 -*-
"""Партия №5, раздел «Силовая электроника»: диоды выпрямителя с
конденсаторным фильтром, дроссельный (Г-образный LC) фильтр выпрямителя,
ток пульсаций и срок службы электролитического конденсатора, прикидка
трансформатора обратноходового (flyback) преобразователя.

Категория — «Электроника» (elektronika): в ней стоят соседние страницы
pulsacii-vypryamitelya, diode-bridge-loss, lc-filtr-raschet,
raschet-transformatora, toroid-turns-al и drossel-impulsnogo. Новый раздел
каталога не вводится.

Источники вписаны прямо в записи (поле sources). WebFetch в окружении агента
недоступен (egress proxy блокирует сайты изготовителей), прямая загрузка
через curl запрещена, поэтому источнику приписано только то, что видно в
поисковой выдаче; где текст виден лишь в пересказе выдачи или на форуме —
так и написано в карточке. Паспортные величины (VRRM, IF(AV), IFSM, ESR,
ток пульсаций, срок службы, Ae, AL, Bmax, VDSS) вводит пользователь; значения
по умолчанию взяты из найденных паспортов, это указано в подсказках.
Эталонные значения тестов посчитаны отдельными скриптами (scratchpad q/ref1–4.py)
с округлением как у toPrecision; формулы там проверены другим путём —
численным интегрированием формы тока, моделированием LC-цепи по времени,
энергетическим балансом и магнитной цепью.

Безопасность. Страницы выпрямителя рассчитаны на вторичную обмотку сетевого
трансформатора — низковольтная часть гальванически отделена от сети. Схем
без трансформаторной развязки нет. Изоляцию, пути утечки и воздушные зазоры
калькуляторы не считают и вердикта о них не дают — это требования стандарта
на изделие (например, IEC 62368-1) и паспортов. Конденсатор после
выпрямителя хранит заряд и после отключения — ссылка на страницу резистора
разряда; совета замыкать конденсатор накоротко нет.
"""

ACCESSED = "02.10.2026"

# Сравнение с допуском и вывод у порога: число рядом с вердиктом показывается
# с таким числом значащих цифр, чтобы округлённое значение лежало по ту же
# сторону порога, что и точное (правило партий №2–4). В отличие от прежних
# партий округлённое значение сравнивается с порогом тоже с допуском — 1e-9
# от модуля порога (так он работает и при отрицательном пороге), а 12 значащих
# цифр вывода заведомо различают числа за пределами допуска. Без допуска
# порог вроде 1,91·0,9 = 1,7189999999999999 «обгонялся» округлённым
# 1,719 на один ULP, и превышение 1,7191 > 1,719 показывалось как
# «1,719 больше 1,719» (найдено тестом партии №5). Цифры добавляются и тогда,
# когда число и порог округляются до одной записи: иначе вышло бы «4,857 ниже
# 4,857» (второй отзыв к PR #25). OPT: необязательное поле —
# пустое даёт null, нечисловое — NaN (строгий ввод сохраняется). pl()/yr() —
# форма слова «год» по показанной строке числа.
Q_JS = r'''
function gt(a,b){return a>b+Math.abs(b)*1e-9;}
function lt(a,b){return a<b-Math.abs(b)*1e-9;}
function ge(a,b){return a>=b-Math.abs(b)*1e-9;}
function le(a,b){return a<=b+Math.abs(b)*1e-9;}
function fx(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-9)return fmt(x,4);for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if((x<lim?lt(r,lim):gt(r,lim))&&r!==Number(lim.toPrecision(p)))return fmt(x,p);}return fmt(x,12);}
function OPT(id){var el=$(id);if(!el)return null;if(String(el.value).trim()==='')return null;return P(id);}
function pl(s,one,few,many,frac){if(/[,·]/.test(s))return frac;var n=Math.abs(parseInt(s,10))%100,n1=n%10;if(n>10&&n<20)return many;if(n1===1)return one;if(n1>=2&&n1<=4)return few;return many;}
function yr(s){return s+' '+pl(s,'год','года','лет','года');}
'''

