js=Q_JS + r'''
function calc(){
var br=S('sch')==='bridge',us=P('us'),f=P('f'),dup=P('dup'),vf=P('vf'),il=P('il'),l=P('l'),c=P('c'),rd=OPT('rdc');
if([us,f,dup,vf,il,l,c].some(isNaN))return err('Заполните числами напряжение обмотки, частоту, превышение напряжения, падение на диоде, ток нагрузки, индуктивность и ёмкость.');
if(us<=0||us>1000)return err('Напряжение обмотки — больше 0 и не больше 1000 В.');
if(f<10||f>1000)return err('Частота сети — от 10 до 1000 Гц.');
if(dup<0||dup>50)return err('Превышение напряжения задаётся от 0 до 50 %.');
if(vf<0||vf>5)return err('Прямое падение на диоде — от 0 до 5 В.');
if(il<=0)return err('Ток нагрузки должен быть больше нуля.');
if(l<=0||c<=0)return err('Индуктивность и ёмкость должны быть больше нуля.');
if(rd!==null){if(isNaN(rd))return err('Сопротивление дросселя и обмоток — число в омах. Если его нет, оставьте поле пустым.');if(rd<0)return err('Сопротивление не может быть отрицательным.');}
var r=rd===null?0:rd,Lh=l/1000,Cf=c*1e-6,w=2*Math.PI*f,wr=2*w,vm=Math.SQRT2*us,vd0=2*vm/Math.PI,nd=br?2:1,vdc=vd0-nd*vf-il*r;
if(!(vdc>0))return err('Падения на диодах и сопротивлении не меньше выпрямленного напряжения — проверьте данные.');
var v2=4*vm/(3*Math.PI),xl=wr*Lh,xc=1/(wr*Cf),v0=vd0-nd*vf;
function zp(R){var a=wr*R*Cf;return [R/(1+a*a),-R*a/(1+a*a)];}
function iac(I){var vd=v0-I*r;if(!(vd>0))return NaN;var z=zp(vd/I);return v2/Math.sqrt((r+z[0])*(r+z[0])+(xl+z[1])*(xl+z[1]));}
var rl=vdc/il,ia=iac(il),z0=zp(rl),vi=v2/il,lc=vi>r+z0[0]?(Math.sqrt(vi*vi-(r+z0[0])*(r+z0[0]))-z0[1])/wr:0,lc0=v2/(wr*il),ic=NaN;
if(xl>xc){var lo=0,hi=v2/(xl-xc);if(r>0)hi=Math.min(hi,v0/r*(1-1e-12));for(var k2=0;k2<200;k2++){var m=(lo+hi)/2;if(iac(m)>m)lo=m;else hi=m;}var q0=(lo+hi)/2;if(Math.abs(iac(q0)-q0)<=q0*1e-9)ic=q0;}
var re=1+r/rl-wr*wr*Lh*Cf,im=xl/rl+wr*r*Cf,g=1/Math.sqrt(re*re+im*im),vr=v2*g,f0=1/(2*Math.PI*Math.sqrt(Lh*Cf)),k=1+dup/100,vnl=Math.SQRT2*us*k,piv=(br?1:2)*vnl,vb=v0-ic*r,rb=vb/ic,pk=vm-nd*vf;
if(![vdc,v2,ia,lc,g,vr,f0].every(isFinite))return err('Значения вне диапазона надёжного расчёта.');
var hc=isFinite(ic),dcm=hc?lt(il,ic):lt(il,ia);
var h=row('Постоянная составляющая выпрямленного напряжения 2√2·U/π',fmt(vd0)+' В')+
 row('Напряжение на нагрузке за вычетом '+(br?'двух диодов':'диода')+(r>0?' и падения I·R':''),fmt(vdc)+' В'+(r>0?'':' — сопротивление дросселя и обмоток не задано'))+
 row('Пульсации на входе фильтра: амплитуда гармоники 2f, 4√2·U/(3π)',fmt(v2)+' В на '+fmt(2*f)+' Гц')+
 row('Резонансная частота f0 = 1/(2π√(LC))',fmt(f0)+' Гц — '+(gt(2*f,f0)?'частота пульсаций выше в '+fmt(2*f/f0)+' раза':(lt(2*f,f0)?'выше частоты пульсаций '+fmt(2*f)+' Гц':'равна частоте пульсаций')))+
 row(r>0?'Коэффициент передачи пульсаций 1/|1 + r/R − (2ω)²LC + j·2ω(L/R + rC)|':'Коэффициент передачи пульсаций 1/|1 − (2ω)²LC + j·2ωL/R|',fx(g,1))+
 row('Пульсации на выходе — размах по первой гармонике',dcm?'не оцениваются: ток дросселя прерывистый':fmt(2*vr)+' В ('+fmt(100*vr/(Math.SQRT2*vdc))+' % действующего от постоянного)')+
 row(r>0?'Переменный ток дросселя на 2f: V2 / |r + j·2ωL + Zc∥Rн|':'Переменный ток дросселя на 2f: V2 / |j·2ωL + Zc∥Rн|',fmt(ia)+' А; без учёта конденсатора V2/(2ωL) — '+fmt(v2/xl)+' А')+
 row('Критическая индуктивность при токе '+fmt(il)+' А с учётом конденсатора и нагрузки',(lc>0?fx(lc*1000,l)+' мГн':'любая')+', задано '+fx(l,lc*1000)+' мГн; без конденсатора 2√2·U/(3π·ω·I) ≈ Rн/(3ω) — '+fmt(lc0*1000)+' мГн')+
 row('Наименьший ток непрерывного режима при этой L',hc?fx(ic,il)+' А':(xl>xc?'не достигается: раньше падение на сопротивлении дросселя и обмоток съедает выпрямленное напряжение':'не оценивается: резонанс фильтра не ниже частоты пульсаций'))+
 row('Пиковый ток дросселя I + Iперем',fmt(il+ia)+' А')+
 row('Нагрузочный резистор, чтобы ток не прерывался без нагрузки',hc?'не больше '+fmt(rb)+' Ом — рассеивает '+fmt(vb*vb/rb)+' Вт':'не оценивается')+
 row('Без нагрузки напряжение растёт до пикового √2·U·(1 + δ)',fmt(vnl)+' В — на него рассчитывают конденсатор')+
 row('Обратное напряжение на диоде '+(br?'√2·U·(1 + δ)':'2·√2·U·(1 + δ)'),fmt(piv)+' В');
var st;
if(!lt(g,1))st='Фильтр не ослабляет пульсации: коэффициент передачи '+fx(g,1)+' — резонансная частота '+fmt(f0)+' Гц '+(lt(f0,2*f)?'слишком близка к частоте пульсаций':'не ниже частоты пульсаций')+' '+fmt(2*f)+' Гц';
else if(dcm)st='Ток дросселя прерывистый: ток нагрузки '+(hc?fx(il,ic)+' А меньше наименьшего тока непрерывного режима '+fx(ic,il):fx(il,ia)+' А меньше переменного тока дросселя '+fx(ia,il))+' А — напряжение выше '+fmt(vdc)+' В и с уменьшением нагрузки растёт к пиковому '+fmt(pk)+' В; формулы непрерывного режима здесь неприменимы';
else st='Оценка: ток дросселя непрерывный, на нагрузке около '+fmt(vdc)+' В, пульсации около '+fmt(2*vr)+' В размаха';
var n='Непрерывный режим: выпрямитель отдаёт полное выпрямленное напряжение, его постоянная составляющая 2√2·U/π ≈ 0,9·U, первая гармоника пульсаций — 2/3 от неё на удвоенной частоте сети. Высшие гармоники (4f, 6f) ослабляются сильнее и в оценку не входят. ';
n+='Переменный ток дросселя — первая гармоника через дроссель и конденсатор с нагрузкой. Классическая формула Lкр ≈ Rн/(3ω) ток через конденсатор не учитывает и занижает критический ток примерно в 1/(1 − (f0/2f)²) раз: при f0 = 49 Гц — почти на треть; это подтвердило моделирование цепи во времени. ';
n+='LC-фильтр — колебательный контур: при включении и скачках нагрузки напряжение кратковременно превышает установившееся, поэтому конденсатор выбирают с запасом. ';
n+='Пиковый ток дросселя сравните с током насыщения по паспорту дросселя. Конденсатор хранит заряд и после отключения — разряжайте его резистором.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">Непрерывный ток дросселя: V<sub>dc</sub> = 2√2·U/π − n·V<sub>f</sub> − I·R ≈ 0,9·U − …<br>Пульсации на входе: амплитуда гармоники 2f — V<sub>2</sub> = 4√2·U/(3π) = (2/3)·2√2·U/π<br>На выходе: V<sub>2</sub> / |1 + r/R<sub>н</sub> − (2ω)²LC + j·2ω(L/R<sub>н</sub> + rC)|, r — сопротивление дросселя и обмоток;&nbsp;&nbsp;без нагрузки — V<sub>2</sub>·X<sub>C</sub>/(X<sub>L</sub> − X<sub>C</sub>)<br>Непрерывность: I ≥ I<sub>перем</sub> = V<sub>2</sub>/|j·2ωL + Z<sub>C</sub>∥R<sub>н</sub>|; без конденсатора L<sub>кр</sub> = 2√2·U/(3π·ω·I) ≈ R<sub>н</sub>/(3ω)<br>f<sub>0</sub> = 1/(2π√(LC)) — заметно ниже 2f</div>
<p><b>Как работает дроссельный вход.</b> Если ток дросселя ни на миг не падает до нуля, диоды выпрямителя проводят всё время, и на входе фильтра — полное выпрямленное напряжение независимо от нагрузки. Дроссель пропускает его постоянную составляющую 2√2·U/π ≈ 0,9·U, а переменную задерживает. Поэтому выходное напряжение ниже, чем с конденсатором на входе (там оно близко к амплитуде), зато почти не зависит от тока, а ток диодов и обмотки — почти прямоугольный, без коротких высоких импульсов.</p>
<p><b>Откуда пульсации.</b> Выпрямленная синусоида раскладывается в ряд Фурье: постоянная 2V<sub>m</sub>/π и чётные гармоники с амплитудами 4V<sub>m</sub>/(π·(n² − 1)), n = 2, 4, 6… В форуме diyAudio это записано в действующих значениях: 0,9·U для постоянной и 1,27·U/(n² − 1) для гармоник. Первая, на удвоенной частоте сети, — 4V<sub>m</sub>/(3π), то есть 2/3 постоянной составляющей; следующая в пять раз меньше и ослабляется фильтром вчетверо сильнее, поэтому в оценку не входит.</p>
<p><b>Ослабление.</b> Дроссель и конденсатор с нагрузкой — делитель напряжения; его коэффициент на частоте ω′ = 2ω равен 1/|1 + r/R<sub>н</sub> − ω′²LC + jω′(L/R<sub>н</sub> + rC)| (комплексные сопротивления, OpenStax); сопротивление дросселя и обмоток r стоит последовательно с L и для переменного тока, поэтому входит и в передачу, и в переменный ток дросселя V<sub>2</sub>/|r + j·2ωL + Z<sub>C</sub>∥R<sub>н</sub>| — у резонанса оно его заметно демпфирует. Без нагрузки это X<sub>C</sub>/(X<sub>L</sub> − X<sub>C</sub>) — так ослабление записывают в учебных материалах; коэффициент пульсаций Г-фильтра там — (√2/3)·X<sub>C</sub>/X<sub>L</sub>. Фильтр — колебательный контур с резонансом f<sub>0</sub> = 1/(2π√(LC)). Если частота пульсаций близка к f<sub>0</sub>, он не ослабляет пульсации, а усиливает: калькулятор считает коэффициент передачи с нагрузкой и при значении не меньше 1 пишет «Фильтр не ослабляет пульсации». Резонанс выбирают заметно ниже 2f.</p>
<p><b>Критическая индуктивность.</b> Почти всё напряжение пульсаций падает на дросселе, и его переменный ток — V<sub>2</sub>/(2ωL). Ток дросселя не прерывается, пока постоянный ток нагрузки не меньше амплитуды переменного: I ≥ V<sub>2</sub>/(2ωL), откуда L ≥ 2√2·U/(3π·ω·I) ≈ R<sub>н</sub>/(3ω). В справочниках это та же величина в числах: Radiotron Designer's Handbook — R<sub>н</sub>/1130 при 60 Гц, ARRL Handbook — R/1100 (оба положения видны в пересказе на форумах); при 50 Гц 3ω ≈ 942. В статье QST 1952 года через неё выражено, насколько пиковый ток превышает средний: L = E/(10·P·I) для P процентов при 60 Гц. Эта классическая оценка не учитывает конденсатор: на частоте 2f его сопротивление вычитается из сопротивления дросселя, и переменный ток больше — примерно в 1/(1 − (f<sub>0</sub>/2f)²) раз. Поэтому калькулятор считает переменный ток через полное сопротивление дросселя и конденсатора с нагрузкой, V<sub>2</sub>/|j·2ωL + Z<sub>C</sub>∥R<sub>н</sub>|, а классическую оценку показывает рядом: при f<sub>0</sub> = 16 Гц разница около 3 %, при 49 Гц — почти треть. Моделирование цепи во времени это подтвердило.</p>
<p><b>Ток ниже критического.</b> Тогда ток дросселя прерывается, фильтр ведёт себя всё больше как фильтр с конденсатором на входе, и напряжение растёт к пиковому √2·U − n·V<sub>f</sub>, а без нагрузки при повышенной сети — до √2·U·(1 + δ). Поэтому конденсатор рассчитывают на пиковое напряжение, а не на V<sub>dc</sub>, а чтобы ток не прерывался, ставят нагрузочный резистор не больше V<sub>dc</sub>/I<sub>кр</sub>: без учёта конденсатора это около 3ωL, с ним — меньше, калькулятор считает точнее. В низковольтном источнике на большой ток такой резистор рассеивает десятки ватт — выгоднее увеличить индуктивность или держать минимальную нагрузку.</p>
<p><b>Чем отличается от LC-фильтра Баттерворта.</b> <a href="lc-filtr-raschet.html">Калькулятор LC-фильтра</a> считает сигнальный ФНЧ второго порядка на заданную частоту среза для источника с малым сопротивлением и активной нагрузки — там важна ровная АЧХ. Здесь источник — выпрямитель, главное — непрерывность тока дросселя и постоянное напряжение, а фильтр должен ослабить пульсации на частоте 2f. Конденсаторный фильтр без дросселя считают <a href="pulsacii-vypryamitelya.html">калькулятор пульсаций</a> и страница <a href="diody-vypryamitelya.html">диодов выпрямителя</a>.</p>
<p><b>Безопасность.</b> Расчёт — для выпрямителя после сетевого трансформатора с гальванической развязкой. Изоляцию, пути утечки и воздушные зазоры калькулятор не проверяет — это требования стандарта безопасности на изделие (например, IEC 62368-1) и паспортов. Конденсатор хранит заряд и после отключения: разряжайте его через <a href="discharge-resistor-capacitor.html">резистор разряда</a>.</p>""",
example="""<p>Мост на обмотке 24 В, 50 Гц, ток 2 А, дроссель 20 мГн, конденсатор 4700 мкФ, V<sub>f</sub> = 1 В. Постоянная составляющая 2·33,94/π = 21,61 В, на нагрузке 21,61 − 2 = <b>19,61 В</b> (сопротивление дросселя и обмоток не учтено). Гармоника 100 Гц на входе — 14,41 В амплитуды. Резонансная частота 16,42 Гц — в 6,092 раза ниже частоты пульсаций; коэффициент передачи 0,02768, на выходе <b>0,7973 В</b> размаха (1,438 %). Переменный ток дросселя — 1,178 А, критическая индуктивность при 2 А — 12 мГн (без учёта конденсатора 11,46 мГн), а 20 мГн больше: ток непрерывен, пока нагрузка не меньше 1,178 А.</p>
<p>При токе 0,5 А ток дросселя станет прерывистым, и напряжение пойдёт вверх — без нагрузки до <b>37,34 В</b> при сети +10 %: конденсатор нужен на 50 В, а не на 25. Нагрузочный резистор для непрерывного тока без нагрузки — не больше 16,64 Ом, но он рассеивает 23,1 Вт. Если взять 470 мкФ, резонанс поднимется до 51,91 Гц, коэффициент передачи вырастет до 0,3335, а пульсации — до 9,607 В размаха.</p>""",
