# ─── 4. Трансформатор обратноходового (flyback) преобразователя ─────────────
# Видно в выдаче: Fairchild (onsemi) AN-4137 — VRO = Dmax/(1 − Dmax)·VDCmin;
# Lm = (VDCmin·Dmax)²/(2·Pin·fs·KRF), KRF = 1 для DCM; IEDC = Pin/(VDCmin·Dmax);
# Ids,peak = IEDC + ΔI/2; Ids,rms = √((3·IEDC² + (ΔI/2)²)·Dmax/3);
# Np,min = Lm·Ilim/(Bsat·Ae)·10⁶, Bsat 0,35–0,4 Тл при отсутствии данных;
