js=Q_JS + r'''
function calc(){
var v1=P('vdcmin'),v2=P('vdcmax'),vo=P('vo'),vf=P('vfo'),po=P('po'),eta=P('eta'),fk=P('fs'),vor=P('vor'),ae=P('ae'),bm=P('bmax');
if([v1,v2,vo,vf,po,eta,fk,vor,ae,bm].some(isNaN))return err('Заполните числами входные напряжения, выход, мощность, КПД, частоту, отражённое напряжение, Ae и Bmax.');
if(!(v1>0)||v2<v1||v2>1500)return err('Входное напряжение: 0 < наименьшее ≤ наибольшее ≤ 1500 В.');
if(vo<=0||vo>1000)return err('Выходное напряжение — больше 0 и не больше 1000 В.');
if(vf<0||vf>5)return err('Падение на выходном диоде — от 0 до 5 В.');
if(po<=0)return err('Выходная мощность должна быть больше нуля.');
if(eta<=0||eta>100)return err('КПД задаётся в процентах: больше 0 и не больше 100.');
if(fk<1||fk>1000)return err('Частота преобразования — от 1 до 1000 кГц.');
if(vor<=0)return err('Отражённое напряжение должно быть больше нуля.');
if(ae<=0)return err('Сечение сердечника Ae должно быть больше нуля.');
if(bm<0.01||bm>2)return err('Наибольшая индукция — от 0,01 до 2 Тл.');
var al=OPT('al'),vd=OPT('vdss'),il=OPT('ilim');
if(al!==null){if(isNaN(al))return err('AL — число в нГн на виток². Если его нет, оставьте поле пустым.');if(al<=0)return err('AL должен быть больше нуля.');}
if(vd!==null){if(isNaN(vd))return err('VDSS — число в вольтах. Если его нет, оставьте поле пустым.');if(vd<=0)return err('VDSS должно быть больше нуля.');}
if(il!==null){if(isNaN(il))return err('Порог ограничения тока — число в амперах. Если его нет, оставьте поле пустым.');if(il<=0)return err('Порог ограничения тока должен быть больше нуля.');}
var fs=fk*1e3,A=ae*1e-6,pin=po/(eta/100),n=vor/(vo+vf),d=vor/(vor+v1),lp=Math.pow(v1*d,2)/(2*pin*fs),ie=pin/(v1*d),di=v1*d/(lp*fs),ip=ie+di/2,irms=Math.sqrt((3*ie*ie+di*di/4)*d/3);
var useLim=il!==null&&ge(il,ip),ib=useLim?il:ip,npm=lp*ib/(bm*A);
if(!isFinite(npm)||npm>1e5)return err('Значения вне диапазона надёжного расчёта.');
var ns=Math.ceil(npm/n*(1-1e-12)),np=Math.ceil(n*ns*(1-1e-12)),np0=np,npl=al===null?0:Math.sqrt(lp/(al*1e-9)),up=al!==null&&lt(np,npl);
if(up){ns=Math.ceil(npl/n*(1-1e-12));np=Math.ceil(n*ns*(1-1e-12));}
var na=np/ns,va=na*(vo+vf),bp=lp*ip/(np*A),mu=4e-7*Math.PI,g=mu*A*(np*np/lp-(al===null?0:1/(al*1e-9))),vds=v2+va,vdo=vo+v2/na,isk=na*ip;
if(![pin,lp,ip,irms,g,vds,vdo,isk].every(isFinite))return err('Значения вне диапазона надёжного расчёта.');
var h=row('Входная мощность Pвых / η',fmt(pin)+' Вт')+
 row('Коэффициент трансформации n = Vor / (Vвых + VF)',fmt(n))+
 row('Наибольший коэффициент заполнения Dmax = Vor / (Vor + Vвх min)',fmt(d))+
 row('Индуктивность первичной обмотки на границе DCM (Vвх min·Dmax)² / (2·Pвх·fs)','не больше '+fmt(lp*1e6)+' мкГн')+
 row('Пиковый ток первичной обмотки 2·Pвх / (Vвх min·Dmax)',(il===null?fmt(ip):fx(ip,il))+' А')+
 row('Действующий ток первичной обмотки Iпик·√(Dmax/3)',fmt(irms)+' А')+
 row('Наименьшее число витков Lp·I / (Bmax·Ae)',fmt(npm)+' — по '+(useLim?'порогу ограничения тока '+fmt(il)+' А':'пиковому току'))+
 (up?row('Витки увеличены по индуктивности сердечника','без зазора AL·Np² при '+np0+' витках — '+fmt(al*np0*np0/1000)+' мкГн, меньше Lp: нужно не меньше √(Lp/AL) = '+fmt(npl)+' витков'):'')+
 row('Витки первичной / вторичной обмотки',np+' / '+ns+' — n = '+fmt(na)+', Vor = '+fmt(va)+' В')+
 row('Индукция при пиковом токе Lp·Iпик / (Np·Ae)',fmt(bp)+' Тл');
if(useLim)h+=row('Индукция при токе ограничения',fmt(lp*il/(np*A))+' Тл');
h+=(g>0?row('Немагнитный зазор без учёта выпучивания '+(al===null?'μ0·Np²·Ae / Lp':'μ0·Ae·(Np²/Lp − 1/AL)'),fmt(g*1000)+' мм — общая длина зазора в магнитной цепи'):row('Немагнитный зазор','не нужен: без зазора AL·Np² = '+fmt(al*np*np/1000)+' мкГн не больше Lp'))+
 row('Напряжение на ключе Vвх max + Vor без выброса',(vd===null?fmt(vds):fx(vds,vd))+' В'+(vd===null?'':' — '+fx(100*vds/vd,70)+' % от VDSS '+fx(vd,vds)+' В'))+
 row('Обратное напряжение на выходном диоде Vвых + Vвх max / n',fmt(vdo)+' В')+
 row('Пиковый ток вторичной обмотки n·Iпик',fmt(isk)+' А');
var st;
if(vd!==null&&gt(vds,vd))st='Напряжение на ключе Vвх max + Vor = '+fx(vds,vd)+' В больше VDSS '+fx(vd,vds)+' В — даже без выброса от индуктивности рассеяния';
else if(il!==null&&lt(il,ip))st='Пиковый ток '+fx(ip,il)+' А больше порога ограничения тока '+fx(il,ip)+' А — при наименьшем входном напряжении заданная мощность не будет отдана';
else if(vd===null)st='Недостаточно данных: VDSS ключа не задано — напряжение на ключе без выброса '+fmt(vds)+' В не с чем сравнить';
else if(gt(vds,0.7*vd))st='Риск: Vвх max + Vor = '+fx(100*vds/vd,70)+' % от VDSS — Fairchild AN-4137 закладывает 65–70 %, остальное — запас на выброс от индуктивности рассеяния';
else st='Оценка: Lp не больше '+fmt(lp*1e6)+' мкГн, '+np+' / '+ns+' витков'+(g>0?', зазор около '+fmt(g*1000)+' мм без учёта выпучивания':'')+'; напряжение на ключе без выброса '+fmt(vds)+' В — '+fx(100*vds/vd,70)+' % от VDSS'+(il===null?'; насыщение при токе ограничения контроллера не проверено — порог не задан':'');
var nt='Прикидка по Fairchild AN-4137 для прерывистого тока: граница DCM — при наименьшем входном напряжении и полной нагрузке; при большем напряжении и меньшей нагрузке ток тем более прерывистый. ';
nt+='Выброс напряжения от индуктивности рассеяния здесь не считается — его ограничивает снаббер, и напряжение на ключе фактически выше Vвх max + Vor. ';
nt+='Зазор — без выпучивания поля: оно увеличивает индуктивность, и нужный зазор больше расчётного; его уточняют по измеренной индуктивности. ';
nt+='Изоляцию между обмотками, пути утечки и воздушные зазоры калькулятор не проверяет — это требования стандарта на изделие (например, IEC 62368-1) и паспортов провода и каркаса. ';
nt+='Первичная сторона и конденсатор сетевого выпрямителя находятся под опасным напряжением и после отключения — разряжайте конденсатор резистором и проверяйте отсутствие напряжения прибором.';
out(h+row('Статус',st)+note(nt));
}
''',
about="""<div class="formula">n = V<sub>or</sub> / (V<sub>вых</sub> + V<sub>F</sub>),&nbsp;&nbsp;D<sub>max</sub> = V<sub>or</sub> / (V<sub>or</sub> + V<sub>вх min</sub>)<br>L<sub>p</sub> = (V<sub>вх min</sub>·D<sub>max</sub>)² / (2·P<sub>вх</sub>·f<sub>s</sub>),&nbsp;&nbsp;P<sub>вх</sub> = P<sub>вых</sub> / η<br>I<sub>пик</sub> = 2·P<sub>вх</sub> / (V<sub>вх min</sub>·D<sub>max</sub>),&nbsp;&nbsp;I<sub>RMS</sub> = I<sub>пик</sub>·√(D<sub>max</sub>/3)<br>N<sub>p</sub> ≥ L<sub>p</sub>·I / (B<sub>max</sub>·A<sub>e</sub>),&nbsp;&nbsp;N<sub>s</sub> = ⌈N<sub>p</sub> / n⌉<br>g ≈ μ<sub>0</sub>·A<sub>e</sub>·(N<sub>p</sub>²/L<sub>p</sub> − 1/A<sub>L</sub>) — без выпучивания поля<br>V<sub>ключа</sub> = V<sub>вх max</sub> + V<sub>or</sub> (без выброса),&nbsp;&nbsp;V<sub>диода</sub> = V<sub>вых</sub> + V<sub>вх max</sub> / n</div>
<p><b>Как работает трансформатор flyback.</b> Пока ключ открыт, ток первичной обмотки растёт, и энергия ½·L<sub>p</sub>·I² копится в зазоре сердечника; вторичная цепь заперта диодом. Когда ключ закрывается, энергия уходит через вторичную обмотку в нагрузку. На первичной обмотке в это время — отражённое напряжение V<sub>or</sub> = n·(V<sub>вых</sub> + V<sub>F</sub>), и ключ видит V<sub>вх</sub> + V<sub>or</sub>. В режиме прерывистого тока (DCM) ток успевает упасть до нуля до следующего такта.</p>
<p><b>Отражённое напряжение и заполнение.</b> На границе прерывистого тока вольт-секунды при открытом и закрытом ключе равны: V<sub>вх</sub>·D = V<sub>or</sub>·(1 − D), откуда D<sub>max</sub> = V<sub>or</sub>/(V<sub>or</sub> + V<sub>вх min</sub>); в AN-4137 то же записано как V<sub>RO</sub> = D<sub>max</sub>/(1 − D<sub>max</sub>)·V<sub>DC min</sub>. Больше V<sub>or</sub> — больше заполнение и меньше пиковый ток, но выше напряжение на ключе. Fairchild советует выбирать D<sub>max</sub> так, чтобы номинальное напряжение на ключе было 65–70 % его VDSS — остальное уходит на выброс от индуктивности рассеяния; для ключа на 650 В и универсальной сети это D<sub>max</sub> 0,45–0,5.</p>
<p><b>Индуктивность на границе DCM.</b> В прерывистом режиме ток каждый такт растёт от нуля: I<sub>пик</sub> = V<sub>вх</sub>·D/(L<sub>p</sub>·f<sub>s</sub>), а энергия такта ½·L<sub>p</sub>·I<sub>пик</sub>², умноженная на f<sub>s</sub>, равна входной мощности. Отсюда L<sub>p</sub> = (V<sub>вх min</sub>·D<sub>max</sub>)²/(2·P<sub>вх</sub>·f<sub>s</sub>) — формула AN-4137 с K<sub>RF</sub> = 1, то есть для DCM. Это наибольшая индуктивность: при большей ток при наименьшем входном напряжении и полной нагрузке перестанет спадать до нуля. Токи — по уравнениям AN-4137: I<sub>пик</sub> = I<sub>EDC</sub> + ΔI/2 и I<sub>RMS</sub> = √((3·I<sub>EDC</sub>² + (ΔI/2)²)·D<sub>max</sub>/3), где I<sub>EDC</sub> = P<sub>вх</sub>/(V<sub>DC min</sub>·D<sub>max</sub>), а в DCM ΔI = 2·I<sub>EDC</sub>. Получается треугольник: I<sub>пик</sub> = 2·P<sub>вх</sub>/(V<sub>вх min</sub>·D<sub>max</sub>), I<sub>RMS</sub> = I<sub>пик</sub>·√(D<sub>max</sub>/3).</p>
<p><b>Число витков.</b> Потокосцепление обмотки L·I равно N·Φ = N·B·A<sub>e</sub> (OpenStax), поэтому индукция при токе I — B = L<sub>p</sub>·I/(N<sub>p</sub>·A<sub>e</sub>), и витков нужно не меньше L<sub>p</sub>·I/(B<sub>max</sub>·A<sub>e</sub>). AN-4137 подставляет сюда не пиковый ток, а порог ограничения тока контроллера: при запуске и перегрузке ток доходит именно до него; если порог задан, калькулятор так и делает. Вторичных витков N<sub>s</sub> = ⌈N<sub>p</sub>/n⌉, первичных — ⌈n·N<sub>s</sub>⌉: фактический коэффициент трансформации не меньше расчётного, и отражённое напряжение не падает — прерывистый режим сохраняется.</p>
<p><b>Зазор.</b> Магнитная цепь с зазором: L = μ<sub>0</sub>·N²·A<sub>e</sub>/(g + l<sub>e</sub>/μ<sub>r</sub>), а сердечник без зазора даёт A<sub>L</sub> = μ<sub>0</sub>·μ<sub>r</sub>·A<sub>e</sub>/l<sub>e</sub>. Отсюда g = μ<sub>0</sub>·A<sub>e</sub>·(N²/L − 1/A<sub>L</sub>) — та же структура, что у формулы зазора в AN-4137, здесь в единицах СИ. Это длина без выпучивания поля. Dixon (TI, SLUP127) поясняет: поле у зазора выходит за пределы керна, эффективная площадь больше, и индуктивность выше расчётной — значит, нужный зазор больше. Таблица TDK для E 25/13/7 из N87 показывает масштаб: A<sub>L</sub> = 151 нГн получается при зазоре 0,5 мм, а формула без выпучивания дала бы 0,40 мм; при 0,16 мм расхождение около 4 %, при 1 мм — около 45 %. Поэтому зазор уточняют по измеренной индуктивности. g — общая длина зазора в магнитной цепи: при зазоре в среднем керне это его длина; прокладка под все керны даёт два зазора последовательно, и её толщина — около g/2, если сечение крайних кернов вместе равно среднему. Если A<sub>L</sub>·N<sub>p</sub>² меньше L<sub>p</sub>, нужной индуктивности не набрать даже без зазора: тогда калькулятор увеличивает число витков до √(L<sub>p</sub>/A<sub>L</sub>), а не пишет, что зазор не нужен, оставляя токи для недостижимой индуктивности.</p>
<p><b>Напряжения.</b> Ключ без учёта выброса видит V<sub>вх max</sub> + V<sub>or</sub>, выходной диод — V<sub>вых</sub> + V<sub>вх max</sub>/n (AN-4137). Выброс от индуктивности рассеяния здесь не считается: его ограничивает снаббер, а считает <a href="rcd-snabber-flyback.html">калькулятор RCD-снаббера</a>. Наименьшее напряжение на входном конденсаторе считают по энергии, которую конденсатор отдаёт между подзарядами: ½·C·(2·U<sub>сети min</sub>² − V<sub>DC min</sub>²) = P<sub>вх</sub>·(1 − D<sub>ch</sub>)/(2·f<sub>сети</sub>), где D<sub>ch</sub> — доля полупериода, когда конденсатор подзаряжается; в AN-4137 она около 0,2.</p>
<p><b>Чем отличается от соседних страниц.</b> <a href="raschet-transformatora.html">Калькулятор сетевого трансформатора</a> — методика для 50 Гц, для импульсных трансформаторов она не подходит. <a href="toroid-turns-al.html">Калькулятор витков по AL</a> даёт витки для заданной индуктивности, но не проверяет индукцию и зазор. <a href="drossel-impulsnogo.html">Дроссель импульсного преобразователя</a> — накопительный дроссель понижающей и повышающей схем.</p>
<p><b>Безопасность.</b> Первичная сторона обратноходового преобразователя связана с сетью; гальваническую развязку даёт сам трансформатор. Изоляцию между обмотками, пути утечки и воздушные зазоры калькулятор не проверяет и вердикта о них не даёт — это требования стандарта безопасности на изделие (например, IEC 62368-1) и паспортов провода, каркаса и изоляционных материалов. Входной конденсатор после сетевого выпрямителя хранит опасный заряд и после отключения: разряжайте его через <a href="discharge-resistor-capacitor.html">резистор разряда</a> и проверяйте отсутствие напряжения прибором.</p>""",
example="""<p>Блок питания 12 В 2 А (24 Вт) от универсальной сети: на входе от 100 до 375 В, КПД 85 %, 65 кГц, V<sub>or</sub> = 75 В, диод с V<sub>F</sub> = 0,5 В. Коэффициент трансформации 75/12,5 = 6, D<sub>max</sub> = 75/175 = 0,4286, входная мощность 28,24 Вт. Индуктивность первичной обмотки — не больше (100·0,4286)²/(2·28,24·65 000) = <b>500,4 мкГн</b>, пиковый ток 1,318 А, действующий 0,498 А.</p>
<p>Сердечник TDK E 25/13/7 из N87: A<sub>e</sub> = 52,5 мм², A<sub>L</sub> без зазора 1850 нГн. При B<sub>max</sub> = 0,3 Тл нужно не меньше 41,86 витка: вторичных 7, первичных <b>42</b>, индукция 0,299 Тл. Зазор без выпучивания μ<sub>0</sub>·52,5·10⁻⁶·(42²/500,4·10⁻⁶ − 1/1850·10⁻⁹) ≈ <b>0,1969 мм</b> — фактически нужен чуть больше. Ключ без выброса видит 375 + 75 = 450 В — 69,23 % от 650 В; выходной диод — 12 + 375/6 = 74,5 В, пиковый ток вторичной обмотки 7,906 А.</p>""",
